#pragma once
#include <vector>
#include <iostream>
#include <iomanip>
#include <cstring>

class Immediate;
void debug_immediate(const Immediate& val);

class RegisterFile {
public:
    static constexpr int REG_NUM = 32;
    Immediate prev[REG_NUM];
    Immediate next[REG_NUM];

    RegisterFile() { memset(prev, 0, sizeof(prev)); memset(next, 0, sizeof(next)); }

    void tick() { memcpy(prev, next, sizeof(prev)); }

    Immediate read(int id) { return id == 0 ? 0 : prev[id]; }

    void write(int id, Immediate val) { next[id] = val; }

    void debug();
};
